source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != background and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(comp)

    seed = max(components, key=len)
    top = min(r for r, c in seed)
    bottom = max(r for r, c in seed)
    left = min(c for r, c in seed)
    right = max(c for r, c in seed)
    anchor_r = (top + bottom) // 2
    anchor_c = (left + right) // 2
    out = [row[:] for row in grid]
    for comp in components:
        if comp is seed:
            continue
        for ar, ac in comp:
            for sr in range(top, bottom + 1):
                for sc in range(left, right + 1):
                    value = grid[sr][sc]
                    if value == background:
                        continue
                    rr = ar + sr - anchor_r
                    cc = ac + sc - anchor_c
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
'''
