def parse_demo_message(idx):
    m=json.loads(lines[idx])['message']
    txt=''.join(c.get('text','') for c in m['content'] if isinstance(c,dict))
    found={}
    for pair in (1,2):
        for kind in ('input','output'):
            pat=rf'Demo pair {pair} {kind} \((\d+)x(\d+)\):\n'
            mt=re.search(pat,txt)
            if mt:
                hh,ww=map(int,mt.groups())
                tail=txt[mt.end():]
                rows=[]
                for ln in tail.splitlines():
                    if len(rows)==hh: break
                    vals=[int(x) for x in ln.split() if x.isdigit()]
                    if vals:
                        rows.append(vals)
                assert len(rows)==hh and all(len(r)==ww for r in rows), (pair,kind,len(rows),[len(r) for r in rows])
                found[(pair,kind)]=rows
    return found
